"""The companion: answers questions from recorded data, proposes actions.

It never performs an action itself. A request that changes something (kill
switch, decision cycle, research run, data refresh) comes back as a
*proposal*; the UI asks for confirmation and calls the real action endpoint,
and only the backend's response is reported as the result.

Answers are labelled by source: "records" (built from the database/broker),
"llm" (generated by the optional LLM from those records), or "system".
"""

from __future__ import annotations

import json
import re
import threading
from collections import deque

from ..config import Settings
from ..models.llm import make_llm
from ..strategies.library import REGISTRY
from . import api

HELP = ("I answer from the system's own records. Try:\n"
        "- Explain current positions / Show my exposure\n"
        "- Why is the agent waiting? / Explain the last decision\n"
        "- Why was that trade rejected?\n"
        "- Summarize today / Show recent errors\n"
        "- Why are you monitoring this asset?\n"
        "- Pause new trades (kill switch), Run a decision cycle, Run a backtest on sma_cross, Refresh data")


def _pct(x):
    return "n/a" if x is None else f"{x * 100:.2f}%"


class Companion:
    def __init__(self, s: Settings, cache: api.BrokerCache, llm=None):
        self.s, self.cache = s, cache
        self.llm = llm or make_llm(s.llm.provider, s.llm.ollama_model, s.llm.anthropic_model, s.llm.timeout_seconds)
        self.history: deque[dict] = deque(maxlen=12)
        self._lock = threading.Lock()
        # (name, pattern) checked in order; the first match wins
        self.intents = [
            ("unkill", r"(turn off|switch off|clear|reset|disable|release|undo|remove)\b.*(emergency|kill|stop)|resume trading|unpause"),
            ("kill",r"\b(pause|halt|stop)\b.*\b(trad|order|proposal)|kill.?switch|emergency"),
            ("run_once", r"run (a |one |the )?(decision )?cycle|run.?once"),
            ("research", r"\bresearch\b|walk.?forward"),
            ("backtest", r"backtest"),
            ("ingest", r"refresh (market )?data|ingest|update (the )?(prices|bars)"),
            ("rejected", r"reject"),
            ("positions", r"position|exposure|holding|portfolio"),
            ("decision", r"decision|waiting|why .*(abstain|hold|not trad)|last (call|action)"),
            ("errors", r"error|fail|warning|problem|alert"),
            ("today", r"today|summar|what happened"),
            ("monitor", r"monitor|watch|why .*(asset|symbol|spy|eurusd)"),
            ("risk", r"\brisk\b|limit|drawdown"),
            ("help", r"^\s*(help|\?|what can you do)"),
        ]

    def ask(self, message: str, context: dict | None = None) -> dict:
        message = (message or "").strip()[:1000]
        if not message:
            return {"reply": HELP, "source": "system"}
        context = context or {}
        low = message.lower()
        intent = next((n for n, p in self.intents if re.search(p, low)), None)
        out = getattr(self, f"_{intent}")(low, context) if intent else self._fallback(message, context)
        out["intent"] = intent
        with self._lock:
            self.history.append({"q": message, "a": out["reply"][:600]})
        return out

    # ------------------------------------------------------------ read-only answers

    def _positions(self, q, ctx):
        br = self.cache.get()
        if not br.get("available"):
            return {"reply": f"I can't read the broker ({br.get('broker')}): {br.get('error')}", "source": "records"}
        pos = br.get("positions") or []
        lines = [f"Broker {br['broker']} ({br['environment']}), equity {br['equity']:,.2f} {br['currency']}, "
                 f"cash {br['cash']:,.2f}."]
        if not pos:
            lines.append("No open positions, so exposure is zero.")
        for p in pos:
            n = api._position_notional(p, br["currency"])
            lines.append(f"- {p['instrument']}: {p['units']:+g} @ {p['avg_price']:.2f}"
                         + (f", notional {n:,.0f} ({n / br['equity']:.1%} of equity)" if n is not None else ""))
        orders = br.get("open_orders")
        if orders is not None:
            lines.append(f"{len(orders)} open order(s) at the broker.")
        return {"reply": "\n".join(lines), "source": "records"}

    def _decision(self, q, ctx):
        rows = api.decision_rows(self.s, 1)
        if not rows:
            return {"reply": "No decision has been recorded yet. Decision cycles run via `tradeintel run-once` "
                             "or `tradeintel service`, or ask me to run one.", "source": "records"}
        d = rows[0]
        lines = [f"Last decision at {d['decided_at'][:19]} UTC: {d['action'].upper()} on {d['instrument']} ({d['strategy']}).",
                 "Recorded reasons: " + "; ".join(d["reasons"] or [])]
        for r in d["reports"] or []:
            extra = r.get("missing") or r.get("objections") or []
            lines.append(f"- {r['agent']}: {r['stance']} ({r['confidence']})" + (f", {'; '.join(extra)}" if extra else ""))
        if not self.s.execution.enabled:
            lines.append("Order submission is disabled (observation only), so no order could be sent regardless.")
        return {"reply": "\n".join(lines), "source": "records", "link": f"#/agents?decision={d['id']}"}

    def _rejected(self, q, ctx):
        for a in api.audit_rows(self.s, 200):
            if a["risk"] and not a["risk"].get("approved"):
                i = a["intent"] or {}
                return {"reply": f"Most recent rejection ({a['at'][:19]} UTC): {i.get('instrument')} "
                                 f"{'long' if i.get('direction') == 1 else 'short'} {i.get('units')} units.\n"
                                 "Risk engine reasons:\n- " + "\n- ".join(a["risk"].get("reasons", [])),
                        "source": "records", "link": "#/execution"}
        return {"reply": "No order intent has been rejected by the risk engine (the audit log has none).", "source": "records"}

    def _errors(self, q, ctx):
        st = api.state(self.s, self.cache)
        lines = [f"[{a['level']}] {a['title']}" + (f": {a['detail']}" if a["detail"] else "") for a in st["alerts"]]
        logs = api.logs_view(self.s, 5, "ERROR")["lines"] + api.logs_view(self.s, 5, "WARNING")["lines"]
        lines += [f"[log {r.get('level')}] {r.get('ts', '')[:19]} {r.get('msg')}" for r in logs[:6]]
        return {"reply": "\n".join(lines) if lines else "No active alerts and no recent ERROR/WARNING log lines.",
                "source": "records", "link": "#/activity"}

    def _today(self, q, ctx):
        today = api._now().date().isoformat()
        ds = [d for d in api.decision_rows(self.s, 200) if d["decided_at"][:10] == today]
        au = [a for a in api.audit_rows(self.s, 200) if a["at"][:10] == today]
        st = api.state(self.s, self.cache)
        acts: dict[str, int] = {}
        for d in ds:
            acts[d["action"]] = acts.get(d["action"], 0) + 1
        lines = [f"Today (UTC {today}): {len(ds)} decision(s)" + (f" ({', '.join(f'{k}: {v}' for k, v in acts.items())})" if acts else "")
                 + f", {len(au)} order attempt(s) in the audit log.",
                 f"Mode: {st['mode']['label']}. Kill switch: {'ENGAGED' if st['kill_switch']['engaged'] else 'clear'}.",
                 f"Data: {st['data']['instrument']} last bar {st['data']['last_bar'] or 'none'}"
                 + (" (stale)" if st["data"]["stale"] else "") + "."]
        if st["broker"].get("available"):
            lines.append(f"Equity {st['broker']['equity']:,.2f} {st['broker']['currency']}, "
                         f"{len(st['broker'].get('positions') or [])} position(s).")
        lines.append(f"{len(st['alerts'])} active alert(s).")
        return {"reply": "\n".join(lines), "source": "records"}

    def _monitor(self, q, ctx):
        sym = ctx.get("symbol") or self.s.market.instrument
        if sym != self.s.market.instrument:
            return {"reply": f"{sym} has stored bars but isn't the traded instrument. The agent only trades "
                             f"{self.s.market.instrument} (config `market.instrument`).", "source": "records"}
        v = api.bars_view(self.s, sym, self.s.market.timeframe, 5, self.cache)
        if not v["available"]:
            return {"reply": f"{sym} is the configured instrument, but {v['error']}.", "source": "records"}
        st = v["strategy"]
        side = {1: "long", -1: "short", 0: "flat"}[st["target"]]
        return {"reply": f"{sym} is the configured instrument (`market.instrument`), traded with {st['describe']}.\n"
                         f"On the latest closed bar the rule says {side}; stop distance {st['stop_dist']:.2f}. "
                         f"Regime: {v['regime']}.\n"
                         "No strategy has passed the promotion gate on real data, so this is observation only.",
                "source": "records", "link": "#/markets"}

    def _risk(self, q, ctx):
        r = api.risk_view(self.s, self.cache)
        lines = ["Emergency stop: " + (f"ON, orders blocked ({r['kill_switch'].get('reason')})" if r["kill_switch"]["engaged"] else "off")]
        for u in r["utilisation"]:
            v = u["value"]
            shown = "n/a" if v is None else (_pct(v) if u["unit"] == "pct" else f"{v:.2f}{'x' if u['unit'] == 'x' else ''}")
            mx = _pct(u["max"]) if u["unit"] == "pct" else u["max"]
            lines.append(f"- {u['limit']}: {shown} (limit {mx})" + (f": {u['note']}" if u["note"] else ""))
        return {"reply": "\n".join(lines), "source": "records", "link": "#/risk"}

    def _help(self, q, ctx):
        return {"reply": HELP, "source": "system"}

    # ------------------------------------------------------------ proposals (never executed here)

    def _kill(self, q, ctx):
        return {"reply": "I can turn on the emergency stop. Every new order is then refused, but it does not sell what you hold "
                         "or cancel orders already at the broker. Turning it off later needs `tradeintel risk reset` in a terminal.",
                "source": "system",
                "proposal": {"action": "kill", "args": {"reason": "assistant request"}, "label": "Stop all new orders",
                             "danger": True}}

    def _unkill(self, q, ctx):
        ks = api.kill_switch(self.s)
        if not ks["engaged"]:
            return {"reply": "The emergency stop is already off.", "source": "records"}
        return {"reply": f"The emergency stop is on ({ks.get('reason', '')}). Turning it off lets new orders through again, "
                         "but only if every other safety check passes. You'll be asked to type RESET.",
                "source": "system",
                "proposal": {"action": "reset-kill", "args": {"confirm": "RESET"}, "label": "Turn off the emergency stop", "danger": True}}

    def _run_once(self, q, ctx):
        return {"reply": "I can run one decision cycle now. It records a decision and, because order submission is "
                         + ("ENABLED, it may send a paper order if a promoted strategy signals and risk approves."
                            if self.s.execution.enabled else "disabled, it can't send an order (dry run)."),
                "source": "system", "proposal": {"action": "run-once", "args": {}, "label": "Run decision cycle",
                                                 "danger": self.s.execution.enabled}}

    def _strategy_in(self, q, ctx):
        return next((n for n in REGISTRY if n in q.replace(" ", "_")), ctx.get("strategy") or self.s.live.strategy)

    def _backtest(self, q, ctx):
        name = self._strategy_in(q, ctx)
        return {"reply": f"I can run an in-sample backtest of {name} on the stored {self.s.market.instrument} bars. "
                         "That is for inspection only, not evidence. For evidence ask for walk-forward research.",
                "source": "system", "proposal": {"action": "backtest", "args": {"strategy": name},
                                                 "label": f"Backtest {name} (in-sample)", "danger": False}}

    def _research(self, q, ctx):
        name = self._strategy_in(q, ctx)
        return {"reply": f"I can run walk-forward research on {name}. It takes a few seconds, adds trials to the "
                         "experiment registry and overwrites the strategy's HTML report.",
                "source": "system", "proposal": {"action": "research", "args": {"strategy": name},
                                                 "label": f"Run research on {name}", "danger": False}}

    def _ingest(self, q, ctx):
        return {"reply": f"I can download and validate fresh {self.s.market.instrument} bars from {self.s.data.provider}.",
                "source": "system", "proposal": {"action": "ingest", "args": {}, "label": "Refresh market data",
                                                 "danger": False}}

    # ------------------------------------------------------------ free text

    def _fallback(self, message, ctx):
        if self.llm.name == "none":
            return {"reply": "I don't have a rule for that, and no LLM is configured (llm.provider: none).\n\n" + HELP,
                    "source": "system"}
        st = api.state(self.s, self.cache)
        facts = {"mode": st["mode"], "kill_switch": st["kill_switch"], "market": st["market"], "data": st["data"],
                 "broker": {k: st["broker"].get(k) for k in ("available", "environment", "equity", "cash", "positions", "quote", "error")},
                 "last_decision": st["agent"]["last_decision"], "alerts": st["alerts"], "ui_context": ctx}
        system = ("You are the assistant inside a demo-only trading research system. Answer ONLY from FACTS. "
                  "If FACTS don't contain the answer, say so. Never claim you performed an action, never promise "
                  "profits, never give personalised investment advice. Be brief. "
                  'Respond as JSON: {"reply": "<text>"}')
        with self._lock:
            hist = list(self.history)[-6:]
        res = self.llm.complete_json(system, json.dumps({"facts": facts, "history": hist, "question": message}, default=str)[:12000])
        reply = res.get("reply") if isinstance(res, dict) else None
        if not isinstance(reply, str) or not reply.strip():
            return {"reply": f"The LLM ({self.llm.name}) gave no usable answer.\n\n" + HELP, "source": "system"}
        return {"reply": reply.strip()[:2000], "source": "llm", "model": self.llm.name}
